function countPaths(grid) {
  // Memoized DFS: paths starting at a cell = 1 + paths starting at each larger neighbour.
  const MOD = 1000000007;
  const m = grid.length, n = grid[0].length;
  const memo = new Map();
  const from = (r, c) => {
    const key = r * n + c;
    if (memo.has(key)) return memo.get(key);
    let ways = 1;
    for (const [x, y] of [[r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]]) {
      if (x >= 0 && x < m && y >= 0 && y < n && grid[x][y] > grid[r][c]) ways = (ways + from(x, y)) % MOD;
    }
    memo.set(key, ways);
    return ways;
  };
  let answer = 0;
  for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) answer = (answer + from(r, c)) % MOD;
  return answer;
}

