function generate(rand, size) {
  const large = size === 'large';
  const rows = large ? 50 + Math.floor(rand() * 51) : 1 + Math.floor(rand() * 3);
  const cols = large ? 50 + Math.floor(rand() * 51) : 1 + Math.floor(rand() * 4);
  const mode = Math.floor(rand() * 4);
  const top = [100000, 3, 12, 100000][mode];
  const grid = [];
  for (let r = 0; r < rows; r++) {
    const row = [];
    for (let c = 0; c < cols; c++) {
      // Mode 3 rises along rows and columns, which creates very many paths.
      row.push(mode === 3 ? r + c + 1 : 1 + Math.floor(rand() * top));
    }
    grid.push(row);
  }
  return [grid];
}
